```python
candidates = sibling_contacts + roommate_contacts
venmo_status = {}
for contact in candidates:
    name = contact['first_name'] + ' ' + contact['last_name']
    email = contact['email']
    results = apis.venmo.search_users(access_token=venmo_access_token, query=email, page_index=0, page_limit=20)
    has_account = False
    if results:
        for user in results:
            if user.get('email') == email:
                has_account = True
                break
    venmo_status[name] = {'email': email, 'phone_number': contact['phone_number'], 'has_venmo': has_account, 'results': results}
print(venmo_status)
```

