```python
def check_venmo_account(name, email):
    # Search by email across all pages
    found = False
    page_index = 0
    while True:
        results = apis.venmo.search_users(access_token=venmo_access_token, query=email, page_index=page_index, page_limit=20)
        if not results:
            break
        for user in results:
            if user.get('email') == email:
                found = True
                break
        if found:
            break
        page_index += 1
    # Also search by full name across all pages
    page_index = 0
    while True:
        results = apis.venmo.search_users(access_token=venmo_access_token, query=name, page_index=page_index, page_limit=20)
        if not results:
            break
        for user in results:
            if user.get('email') == email:
                found = True
                break
        if found:
            break
        page_index += 1
    return found

targets = []
for contact in sibling_contacts + roommate_contacts:
